22,1788,1087,"beijianshahezi"},h)g[402402]=b({e[11034],402402,1,4,142,"「もうすぐ夏ね〜。あなたと出会ってから初めての夏、すごく楽しみにしてるのよ」",200024,1,"deco/character/beijianshahezi_0",302002,60,1894,853,400,872,485,2478,2899,1110,552,2002,1261,false,false,false,false,false,false,false,false,false,false,false,false,"beijianshahezi_0"},h)g[402403]=b({e[9034],402403,4,77,143,"「子どもたちにクリスマスプレゼントを用意する時に、あなたの分も用意しておいたのよ！　さぁ、はやくこっちに座って。プレゼントを見たあなたがどんなリアクションを見せてくれるのか、楽しみだわ。」",200024,2,"deco/character/beijianshahezi_SD",1804,982,376,832,143,2336,2894,832,669,2336,1261,false,false,false,false,false,false,false,false,false,false,false,false,"beijianshahezi_sd"},h)g[402404]=b({e[12034],402404,12,37,144,"「シーッ。こんな素敵な夜はただ楽しむだけでいいの。主婦は時間管理が大事、この時間も有効活用しないと。そうね……今なんかは、お酒とダンスをめいっぱい楽しまなきゃ！」",200024,2,"deco/character/beijianshahezi_LF",false,false,1,1809,851,361,1033,715,2290,2269,1033,715,2290,1077,false,false,false,false,false,false,false,false,false,false,false,false,"beijianshahezi_lf"},h)g[402405]=b({e[21034],402405,9,78,145,"「一日中忙しくて、この時間くらいしか気が休まらないのよね……。ごめんなさい、つい愚痴っちゃって……あら？　ふふっ、幸せそうな寝顔。聞かれたかなんて、心配するまでもなさそうね。」",200024,2,"deco/character/beijianshahezi_SY",false,false,false,false,false,false,false,"1",false,false,false,"0,-140,1",1671,924,390,866,424,2952,2616,891,618,2902,1261,false,false,false,false,false,false,false,false,false,false,false,false,"beijianshahezi_sy"},h)g[402406]=b({e[21034],402406,16,43,146,"「あら……君に見つめられちゃうなんて、なんだかいい気分ね。でも、私なんかより、ハンドルの方に集中しなきゃダメよ。だって……万が一コースアウトでもしちゃったら、大惨事でしょう？」",200024,2,"deco/character/beijianshahezi_SC",false,false,1,false,false,false,false,"1",false,false,false,"240,-320,1",1893,813,390,815,258,2742,2640,815,507,2742,1261,1,4464,5000,2170,2840,13333,13333,13333,13333,12000,8000,13333,"beijianshahezi_sc"},h)g[402407]=b({e[9045],402407,13,57,147,"「あら？　もうこんな時間……。うふふ……ここはお湯加減もちょうど良いし、邪魔も入らないから……つい長湯しちゃうわね。でも、たまには細かいことを忘れて、ゆ～っくり羽を伸ばしても、大丈夫よね？」",200024,2,"deco/character/beijianshahezi_WQ",1,2816,5000,1390,889,10666,8000,5633,4333,14000,8000,5333,"beijianshahezi_wq"},h)g[402501